mkdir -p .copilot-tracking/skraft-plans/pricing/features .copilot-tracking/skraft-plans/pricing/details/2026-11-25 tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > .copilot-tracking/skraft-plans/pricing/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier reduction at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver, Gold (AC-1 to AC-4).
  # NOT DECIDED: Platinum. The business has not agreed a reduction, so no scenario
  # exists and none may be invented. Add one only when a Decision: line gives the value.

  @happy-path @smoke
  Scenario: S1 Bronze customer is charged 9500 cents on a 10000 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: S2 Silver customer is charged 9000 cents on a 10000 cent basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: S3 Gold customer is charged 8500 cents on a 10000 cent basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: S4 Bronze customer with a 7 cent basket is charged 7 cents
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cd tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > CalculateLoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _handler = new();

    [Fact]
    // S1 Bronze customer is charged 9500 cents on a 10000 cent basket
    public void S1_BronzeBasketOf10000CentsIsCharged9500Cents()
    {
        var quote = _handler.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }

    [Fact]
    // S2 Silver customer is charged 9000 cents on a 10000 cent basket
    public void S2_SilverBasketOf10000CentsIsCharged9000Cents()
    {
        var quote = _handler.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    [Fact]
    // S3 Gold customer is charged 8500 cents on a 10000 cent basket
    public void S3_GoldBasketOf10000CentsIsCharged8500Cents()
    {
        var quote = _handler.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }

    [Fact]
    // S4 Bronze customer with a 7 cent basket is charged 7 cents
    public void S4_BronzeBasketOf7CentsIsCharged7Cents()
    {
        var quote = _handler.Handle(new CalculateLoyaltyDiscountQuery(7, LoyaltyTier.Bronze));

        Assert.Equal(7, quote.TotalCents);
    }
}
EOF
